<div className="page-heading"><div><div className="eyebrow">BRAZILIAN SOCCER TRAINING CENTER</div><h1>{page==='Overview'?'Your club, at a glance.':page==='Dashboard'?'Welcome to your soccer season.':page}</h1><p>{page==='Overview'?'More time on the field. Less time on the paperwork.':page==='Seasons'?'Great seasons start with a little planning.':page==='Dashboard'?'Your players, registrations, and payments. All in one place.':page==='Registrations'?'Keep every player’s next step moving forward.':page==='Available seasons'?'Find the right place for your player to grow.':'Everything you need, organized for your club.'}</p></div><div className="heading-actions">{!portal&&<button className="btn secondary" onClick={()=>open('Export')}><Download size={16}/>Export</button>}<button className="btn primary" onClick={()=>page==='Seasons'?writable()&&open('Season',{status:'Draft',price:450,capacity:30,min_age:6,max_age:12,waiver:waiverText,questions:'[]'}):portal&&page==='My family'?writable()&&open('Player',{}):open('Choose season')}><Plus size={17}/>{page==='Seasons'?'Create season':portal&&page==='My family'?'Add player':'New registration'}</button></div></div>
