{page==='Reports & exports'&&<section className="card export-page"><div className="export-icon"><ChartNoAxesCombined size={32}/></div><h2>Your club data, ready to work.</h2><p>Export a roster, reconcile payments, or securely connect Google Sheets.</p><div className="export-choices"><button className="card" onClick={()=>open('Export')}><Download/><strong>Download a spreadsheet</strong><span>CSV or Excel · Choose your columns</span><ArrowRight/></button><button className="card" onClick={()=>writable()&&(location.href='/api/google/connect')}><ChartNoAxesCombined/><strong>Connect Google Sheets</strong><span>Secure Google authorization</span><ArrowRight/></button></div><p className="privacy-note"><ShieldCheck size={16}/>Medical information is excluded from standard exports.</p></section>}
